Here is the commit message:
net/sched: cls_fw: fix NULL pointer dereference on shared
 blocks

The old-method path in fw_classify() calls tcf_block_q() and
dereferences q->handle.  Shared blocks leave block->q NULL, causing a
NULL deref when an empty cls_fw filter is attached to a shared block
and a packet with a nonzero major skb mark is classified.

Reject the configuration in fw_change() when the old method (no
TCA_OPTIONS) is used on a shared block, since fw_classify()'s
old-method path needs block->q which is NULL for shared blocks.

The fixed null-ptr-deref calling stack:
 KASAN: null-ptr-deref in range [0x0000000000000038-0x000000000000003f]
 RIP: 0010:fw_classify (net/sched/cls_fw.c:81)
 Call Trace:
  tcf_classify (./include/net/tc_wrapper.h:197 net/sched/cls_api.c:1764 net/sched/cls_api.c:1860)
  tc_run (net/core/dev.c:4401)
  __dev_queue_xmit (net/core/dev.c:4535 net/core/dev.c:4790)

Fixes: 1abf272022cf ("net: sched: tcindex, fw, flow: use tcf_block_q helper to get struct Qdisc")
Reported-by: Weiming Shi <bestswngs@gmail.com>
Signed-off-by: Xiang Mei <xmei5@asu.edu>
Acked-by: Jamal Hadi Salim <jhs@mojatatu.com>
Link: https://patch.msgid.link/20260331050217.504278-1-xmei5@asu.edu
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The old-method path in fw_classify() calls tcf_block_q() which returns NULL for shared blocks (since block->q is NULL), then dereferences q->handle, leading to a NULL pointer dereference when an empty cls_fw filter is attached to a shared block and a packet with a nonzero major skb mark is classified.

Here is the patch:

 static int fw_change(struct net *net, struct sk_buff *in_skb,
 		     struct tcf_proto *tp, unsigned long base,
 		     u32 handle, struct nlattr **tca, void **arg,
 		     u32 flags, struct netlink_ext_ack *extack)
 {
 	struct fw_head *head = rtnl_dereference(tp->root);
 	struct fw_filter *f = *arg;
 	struct nlattr *opt = tca[TCA_OPTIONS];
 	struct nlattr *tb[TCA_FW_MAX + 1];
 	int err;

-	if (!opt)
-		return handle ? -EINVAL : 0; /* Succeed if it is old method. */
+	if (!opt) {
+		if (handle)
+			return -EINVAL;
+
+		if (tcf_block_shared(tp->chain->block)) {
+			NL_SET_ERR_MSG(extack,
+				       "Must specify mark when attaching fw filter to block");
+			return -EINVAL;
+		}
+
+		return 0; /* Succeed if it is old method. */
+	}

 	err = nla_parse_nested_deprecated(tb, TCA_FW_MAX, opt, fw_policy,
 					  NULL);
 	if (err < 0)
 		return err;

 	if (f) {
 		struct fw_filter *pfp, *fnew;
 		struct fw_filter __rcu **fp;

 		if (f->id != handle && handle)
 			return -EINVAL;

 		fnew = kzalloc_obj(struct fw_filter);
 		if (!fnew)
 			return -ENOBUFS;

 		fnew->id = f->id;
 		fnew->ifindex = f->ifindex;
 		fnew->tp = f->tp;

 		err = tcf_exts_init(&fnew->exts, net, TCA_FW_ACT,
 				    TCA_FW_POLICE);
 		if (err < 0) {
 			kfree(fnew);
 			return err;
 		}

 		err = fw_set_parms(net, tp, fnew, tb, tca, base, flags, extack);
 		if (err < 0) {
 			tcf_exts_destroy(&fnew->exts);
 			kfree(fnew);
 			return err;
 		}

 		fp = &head->ht[fw_hash(fnew->id)];
 		for (pfp = rtnl_dereference(*fp); pfp;
 		     fp = &pfp->next, pfp = rtnl_dereference(*fp))
 			if (pfp == f)
 				break;

 		RCU_INIT_POINTER(fnew->next, rtnl_dereference(pfp->next));
 		rcu_assign_pointer(*fp, fnew);
 		tcf_unbind_filter(tp, &f->res);
 		tcf_exts_get_net(&f->exts);
 		tcf_queue_work(&f->rwork, fw_delete_filter_work);

 		*arg = fnew;
 		return err;
 	}

 	if (!handle)
 		return -EINVAL;

 	if (!head) {
 		u32 mask = 0xFFFFFFFF;
 		if (tb[TCA_FW_MASK])
 			mask = nla_get_u32(tb[TCA_FW_MASK]);

 		head = kzalloc_obj(*head);
 		if (!head)
 			return -ENOBUFS;
 		head->mask = mask;

 		rcu_assign_pointer(tp->root, head);
 	}

 	f = kzalloc_obj(struct fw_filter);
 	if (f == NULL)
 		return -ENOBUFS;

 	err = tcf_exts_init(&f->exts, net, TCA_FW_ACT, TCA_FW_POLICE);
 	if (err < 0)
 		goto errout;
 	f->id = handle;
 	f->tp = tp;

 	err = fw_set_parms(net, tp, f, tb, tca, base, flags, extack);
 	if (err < 0)
 		goto errout;

 	RCU_INIT_POINTER(f->next, head->ht[fw_hash(handle)]);
 	rcu_assign_pointer(head->ht[fw_hash(handle)], f);

 	*arg = f;
 	return 0;

 errout:
 	tcf_exts_destroy(&f->exts);
 	kfree(f);
 	return err;
 }



